import{_ as i,a0 as l,w as o,s as n,ao as m,I as p,x as t,a1 as r,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"使用一塊樹莓派主板測量圓周率 | LCTT x X-CMD","titleTemplate":false,"description":"使用一塊樹莓派主板測量圓周率 | LCTT (202304) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用一塊樹莓派主板測量圓周率 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用一塊樹莓派主板測量圓周率 | LCTT (202304) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202304/20230331.2 ⭐️⭐️ Measure pi with a Raspberry Pi","title":"使用一塊樹莓派主板測量圓周率","tag":"202304","desc":""},"relativePath":"202304/20230331.2 ⭐️⭐️ Measure pi with a Raspberry Pi.md","filePath":"[post].md"}'),u={name:"202304/20230331.2 ⭐️⭐️ Measure pi with a Raspberry Pi.md"};function d(f,e,h,g,b,T){const a=l("Link");return o(),n("div",null,[e[15]||(e[15]=m('<h1 id="使用一塊樹莓派主板測量圓周率" tabindex="-1">使用一塊樹莓派主板測量圓周率 <a class="header-anchor" href="#使用一塊樹莓派主板測量圓周率" aria-label="Permalink to “使用一塊樹莓派主板測量圓周率”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202304/13/120203upp4tb199bbhpp59.jpg" alt=""></p><blockquote><p>用你的樹莓派製作一個接近完美的圓。</p></blockquote><p>世界各地將 3 月 14 日定為圓周率日。許多人通過在房子周圍找到的物體測量圓周率來慶祝圓周率日。我想用我的樹莓派 3B 為今年的圓周率日做一些類似的事情。繼續閲讀以瞭解我如何使用我的樹莓派測量圓周率。</p><p>你需要什麼：</p><ul><li>樹莓派單板機</li><li>方格紙</li><li>帶毫米和釐米測量值的標尺</li><li>筆</li></ul><h3 id="_1、畫一個圓" tabindex="-1">1、畫一個圓 <a class="header-anchor" href="#_1、畫一個圓" aria-label="Permalink to “1、畫一個圓”">​</a></h3><p>圓周率是圓的周長與其直徑的比值。要計算圓周率，我們需要測量一個完美繪製的圓的周長和直徑。幸運的是，樹莓派主板上的安裝孔足夠大，可以使用鉛筆或鋼筆。我通過一個樹莓派板安裝孔插入了一根圖釘，小心地將針放在一張方格紙上兩條線的交點上。</p><p>握住別針，我將一支筆插入對面的安裝孔中，並通過將筆繞着別針移動來畫一個圓圈。樹莓派主板底面的焊點會卡在紙上，但小心點還是可以畫好圓圈的。</p><p><img src="https://opensource.com/sites/default/files/2023-03/10000000000003E8000003E8BE7DE71919BB0C82.jpg" alt="Use the Raspberry Pi as a compass to draw a circle."></p><h3 id="_2、把圓分成段" tabindex="-1">2、把圓分成段 <a class="header-anchor" href="#_2、把圓分成段" aria-label="Permalink to “2、把圓分成段”">​</a></h3><p>通過畫一條穿過圓心的垂直線將圓分成兩半，通過畫一條穿過圓心的水平線將圓再次分成四分之一。當我畫圓的時候，我把圖釘正好放在圖畫紙上兩條線的交點上，這樣就很容易找到垂直和水平的中心線。你可以通過在對角線上畫一條線來創造一個 “八分” 片。</p><p><img src="https://opensource.com/sites/default/files/2023-03/100000010000028A0000028A0625B218857F031C.webp" alt="Each small wedge is 1/8 of a circle."></p><p>進一步的劃分是與尺子的練習。我用尺子找到“四分之一楔形”和“八分之一楔形”任意兩個交點的中點，做成一個 1/16 的楔形。你可以使用相同的方法制作越來越小的 1/32 和 1/64 圓的切片。通過非常小心，我還能夠在圓的 1/128 處測量出一個非常窄的楔形：</p><p><img src="https://opensource.com/sites/default/files/2023-03/100000000000079E00000514506C8EE5131D886A.webp" alt="If you are careful, you can keep dividing to find 1/128 of a circle."></p><h3 id="_3、估算周長" tabindex="-1">3、估算周長 <a class="header-anchor" href="#_3、估算周長" aria-label="Permalink to “3、估算周長”">​</a></h3><p>我最小的楔形是一個圓的 1/128。如此小的切片，楔形的外弧非常小，我們可以用一條直線來近似它。這實際上不是圓周長的 1/128，但它足夠接近，我們可以將其用作一個很好的估計。</p><p><img src="https://opensource.com/sites/default/files/2023-03/10000000000003E8000003E881402FB71F1945FF.jpg" alt="Use the mm measurement on your ruler to measure the outer arc of the 1/128 segment."></p><p>使用我的尺子上的毫米測量值，我測量了我的 1/128 楔形的外弧為 3.8 毫米。這樣，我可以估計圓的周長為 3.8 毫米乘以 128，即 486.4 毫米。要轉換為釐米，除以十：<strong>48.64cm</strong>。</p><h3 id="_4、計算圓周率" tabindex="-1">4、計算圓周率 <a class="header-anchor" href="#_4、計算圓周率" aria-label="Permalink to “4、計算圓周率”">​</a></h3><p>圓周率的值是圓的周長與其直徑的比值。我們在步驟 3 中估算了周長。測量直徑是使用尺子測量圓周的簡單練習。我的圓是 <strong>15.4cm</strong>。</p><p>現在我們知道了周長和直徑，我們可以將圓周率計算為 48.64 除以 15.4，即 <strong>3.158</strong>。這與 pi 的實際值 3.141 相差不遠。</p><p>測量圓周率是一項有趣的數學練習！各個年齡段的數學愛好者都可以使用方格紙、筆和尺子等簡單工具自行測量圓周率。以一種有趣的新方式使用你的樹莓派來繪製圓並獨立測量圓周率。這是一個估計值，因為我們將圓上的 1/128 弧近似為一條直線，但這使我們無需太多努力就足夠接近了。</p><p>（LCTT 校注：這真是對樹莓派的“合理”應用，摔！）</p><p><em>（題圖：MJ: Circumference in high resolution, very detailed）</em></p><hr>',26)),p("p",null,[e[1]||(e[1]=t("via: ",-1)),r(a,{href:"https://opensource.com/article/23/3/measure-pi-raspberry-pi"},{default:s(()=>[...e[0]||(e[0]=[t("https://opensource.com/article/23/3/measure-pi-raspberry-pi",-1)])]),_:1})]),p("p",null,[e[6]||(e[6]=t("作者：",-1)),r(a,{href:"https://opensource.com/users/jim-hall"},{default:s(()=>[...e[2]||(e[2]=[t("Jim Hall",-1)])]),_:1}),e[7]||(e[7]=t(" 選題：",-1)),r(a,{href:"https://github.com/lkxed/"},{default:s(()=>[...e[3]||(e[3]=[t("lkxed",-1)])]),_:1}),e[8]||(e[8]=t(" 譯者：",-1)),r(a,{href:"https://github.com/geekpi"},{default:s(()=>[...e[4]||(e[4]=[t("geekpi",-1)])]),_:1}),e[9]||(e[9]=t(" 校對：",-1)),r(a,{href:"https://github.com/wxy"},{default:s(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),p("p",null,[e[12]||(e[12]=t("本文由 ",-1)),r(a,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原創編譯，",-1)),r(a,{href:"https://linux.cn/"},{default:s(()=>[...e[11]||(e[11]=[t("Linux中國",-1)])]),_:1}),e[14]||(e[14]=t(" 榮譽推出",-1))])])}const c=i(u,[["render",d]]);export{_ as __pageData,c as default};
